def matrixfy(name: str) -> list[list[str]]:
    if len(name) == 0:
        return "name must be at least one letter"

    n = len(name)
    side = 1
    while side * side < n:
        side += 1

    matrix = []
    index = 0
    for _ in range(side):
        row = []
        for _ in range(side):
            if index < n:
                row.append(name[index])
                index += 1
            else:
                row.append('.')
        matrix.append(row)

    return matrix
